g=[[0]*20 for _ in range(20)]
noise={(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)}
for r,c in noise: g[r][c]=1
for r in range(2,9):
    for c in range(9,16): g[r][c]=2
for r in range(2,9):
    left=any((r,c) in noise for c in range(0,9))
    right=any((r,c) in noise for c in range(16,20))
    if not left: g[r][0:9]=[2]*9
    if not right: g[r][16:20]=[2]*4
for c in range(9,16):
    below=any((r,c) in noise for r in range(9,20))
    above=any((r,c) in noise for r in range(0,2))
    if not below:
        for r in range(9,20): g[r][c]=2
    if not above:
        for r in range(0,2): g[r][c]=2
for row in g: print(''.join(map(str,row)))
import json
print(json.dumps({"action":"submit","grid":g}))
